typedef float rational_t;

extern "C" float sqrtf(float);
extern rational_t *fast_acos_lookup_table;

struct vector3d
{
  rational_t x;
  rational_t y;
  rational_t z;
};

struct po
{
  char padding[32];
  vector3d z_facing;

  const vector3d& get_z_facing() const { return z_facing; }
  const vector3d& get_facing() const { return get_z_facing(); }
};

class entity
{
  char padding[80];
  po *my_abs_po;

public:
  const po& get_abs_po() const { return *my_abs_po; }
};

inline rational_t safe_atan2(rational_t x, rational_t y)
{
  rational_t res = 0.0f;

  if(x != 0.0f || y != 0.0f)
  {
    res = (x*x) + (y*y);
    res = sqrtf(res);
    res = y / res;

    res = fast_acos_lookup_table[(int)((res+1.0f)*8192.0f)];

    if(x < 0.0f)
      res = -res;
  }

  return(res);
}

class ai_locomotion
{
public:
  entity *get_my_entity() const;
  rational_t get_xz_rotation_to_dir( const vector3d &dir ) const;
};

rational_t ai_locomotion::get_xz_rotation_to_dir( const vector3d &dir ) const
{
  vector3d face = get_my_entity()->get_abs_po().get_facing();

  rational_t diff = safe_atan2( -dir.x, dir.z ) - safe_atan2( -face.x, face.z );

  if( diff > 3.14159265358979323846f )
    diff -= 6.28318530717958647692f;
  if( diff < -3.14159265358979323846f )
    diff += 6.28318530717958647692f;

  return( diff );
}
